const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laPoint = ee.Geometry.Point(-118.2436826460509, 33.97811334086217);
  const sdPoint = ee.Geometry.Point(-117.15380986802357, 32.7358717958782);
  const startDate = '2018-01-01';
  const endDate = '2019-12-31';
  const scale = 1000; // S5P nominal resolution is ~1km

  // 2. Data Acquisition & Check
  const s5p = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(startDate, endDate)
    .select('NO2_column_number_density', 'qa_value');

  // Function to process each location
  const processLocation = async (name, geometry) => {
    let collection = s5p.filterBounds(geometry);

    const initialSize = await collection.size().getInfo();
    if (initialSize === 0) {
      console.log(`No images found for ${name} within the date range.`);
      return { value: null, pixelCount: 0, initialImages: 0 };
    }

    // Apply QA value filter (values > 0.75 are good quality)
    collection = collection.map(image => image.updateMask(image.select('qa_value').gt(0.75)));

    const processedSize = await collection.size().getInfo();
    if (processedSize === 0) {
      console.log(`No images for ${name} after QA masking.`);
      return { value: null, pixelCount: 0, initialImages: initialSize };
    }

    // Calculate mean NO2 and valid pixel count
    const meanNO2 = collection.mean();

    const stats = await meanNO2.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const value = stats ? stats['NO2_column_number_density'] : null;
    const pixelCount = stats ? stats['NO2_column_number_density_count'] : 0;

    return { value, pixelCount, initialImages: initialSize };
  };

  console.log(`Analyzing NO2 from ${startDate} to ${endDate} at scale ${scale}m`);

  const laData = await processLocation('Los Angeles', laPoint);
  const sdData = await processLocation('San Diego', sdPoint);

  console.log(`LA - Images: ${laData.initialImages}, Valid Pixels: ${laData.pixelCount}, NO2: ${laData.value !== null ? laData.value.toExponential(2) : 'N/A'}`);
  console.log(`SD - Images: ${sdData.initialImages}, Valid Pixels: ${sdData.pixelCount}, NO2: ${sdData.value !== null ? sdData.value.toExponential(2) : 'N/A'}`);

  // 5. Validation & Final Answer
  if (laData.initialImages === 0 || sdData.initialImages === 0) {
    console.log("C1"); // One or both collections were empty initially
    return;
  }

  if (laData.pixelCount === 0 || sdData.pixelCount === 0) {
    console.log("C2"); // No valid pixels after masking for one or both locations
    return;
  }

  if (laData.value === null || isNaN(laData.value) || sdData.value === null || isNaN(sdData.value)) {
    console.log("C3"); // Calculation failed (NaN or null)
    return;
  }

  // Convert to scientific notation for comparison, as values are very small
  const laNO2 = laData.value;
  const sdNO2 = sdData.value;

  if (laNO2 > sdNO2) {
    console.log("A"); // LA has higher NO2
  } else {
    console.log("B"); // SD has higher or equal NO2
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
